pub fn ota_start(post: bool, busy: bool, has_target: bool, total: u32, max_size: u32) -> OtaStart {
    if !post {
        OtaStart::MethodNotAllowed
    } else if busy {
        OtaStart::Conflict
    } else if !has_target {
        OtaStart::NoTarget
    } else if total == 0 || total > max_size {
        OtaStart::BadRequest
    } else {
        OtaStart::Stream
    }
}

