pub fn range(f: Field) -> (i32, i32) {
    match f {
        Field::PupilLength => (20, 120),
        Field::WiggleAmp => (0, 400),
        Field::BlinkInterval => (60, 600),
        Field::EyeRed => (0, 31),
        Field::EyeGreen => (0, 63),
        Field::EyeBlue => (0, 31),
        Field::SoundThreshold => (10, 400),
        _ => (0, 100),
    }
}

