Wifi.kernel_code:
pub enum Wifi {
    /// Store this name (or, without one, the stored config unchanged) and
    /// restart into it: `200 restarting`.
    StoreAndRestart,
    /// An empty name or one over 32 bytes: `400`, nothing stored, no
    /// restart (upstream stores an empty name).
    Refuse,
}

upstream.code:
pub async fn set(Form(query): Form<WifiQuery>) -> impl IntoResponse {
  let mut stored = cotl::storage::StoredConfig::load().await;
  if let Some(new_ssid) = query.ssid {
    stored.ssid = new_ssid.as_str().try_into().unwrap_or_default();
  }
  stored.save().await;
  cotl::control::RESTART_REQUESTED.store(true, Relaxed);
  (StatusCode::OK, "restarting")
}

wifi_set.kernel_code:
pub fn wifi_set(given: bool, len: u32) -> Wifi {
    if !given {
        Wifi::StoreAndRestart
    } else if len == 0 || len > SSID_MAX_LEN {
        Wifi::Refuse
    } else {
        Wifi::StoreAndRestart
    }
}

